const $=(id)=>document.getElementById(id); const valuation=$("valuation"), out=$("valuationOut");
valuation.addEventListener("input",()=>out.value=`¥${(Number(valuation.value)/100).toFixed(2)}`);
document.querySelectorAll(".tab").forEach((button)=>button.addEventListener("click",()=>{document.querySelectorAll(".tab,.panel").forEach((el)=>el.classList.remove("active"));button.classList.add("active");$(button.dataset.tab).classList.add("active");if(button.dataset.tab==="monitor")loadMonitoring();}));
function yenMicros(value){return `¥${(Number(value)/1_000_000).toFixed(2)}`}
async function evaluate(){const response=await fetch("/api/evaluate",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({amountJpy:Number($("amount").value),residualValueJpyPerUnit:(Number(valuation.value)/100).toFixed(2),pointCardPresented:$("pointCard").checked,campaignEnrolled:$("campaign").checked})});const data=await response.json();if(!response.ok)throw new Error(data.error);render(data)}
function render(data){const label=(id)=>id==="direct_card"?"Direct demo card":"Top up demo wallet";$("winner").innerHTML=`<div class="winner"><div>Recommended</div><div class="route">${label(data.winner.planId)}</div><div class="score">${yenMicros(data.winner.netValueMicros)}</div><div>modeled incremental value</div></div>`;$("plans").innerHTML=data.plans.map((p)=>`<article class="plan"><h3>${label(p.planId)}</h3><div class="metric"><span>External funding</span><b>¥${p.externalFundingJpy}</b></div><div class="metric"><span>Residual units</span><b>${p.residualUnits}</b></div><div class="metric"><span>Reward value</span><b>${yenMicros(p.rewardValueMicros)}</b></div><div class="metric"><span>Net value</span><b>${yenMicros(p.netValueMicros)}</b></div><ol class="steps">${p.steps.map((s)=>`<li>${s}</li>`).join("")}</ol></article>`).join("");$("explanation").innerHTML=`<div class="explanation"><b>Why</b><ul>${data.explanation.map((x)=>`<li>${x}</li>`).join("")}</ul></div>`}
async function loadMonitoring(){const data=await (await fetch("/api/monitoring")).json();$("streams").innerHTML=data.streams.map((s)=>`<div class="stream"><div><b>${s.streamId}</b><div>${s.note}</div><small>Last terminal run: ${s.lastTerminalRunAt}</small></div><span class="pill ${s.status}">${s.status}</span></div>`).join("")}
$("form").addEventListener("submit",(e)=>{e.preventDefault();evaluate().catch((error)=>alert(error.message))});evaluate();
